use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn sign_val(x: i8) -> i8 {
    if x < 0 {
        -1
    } else if x > 0 {
        1
    } else {
        0
    }
}

fn sign(x: Vec<i8>) -> (result: Vec<i8>)
    ensures
        result.len() == x.len(),
        forall|i: int| 0 <= i && i < x.len() ==> result[i] == sign_val(x[i]),
{
    let mut result = Vec::with_capacity(x.len());
    let mut index: usize = 0;
    
    while index < x.len()
        invariant
            0 <= index <= x.len(),
            result.len() == index,
            forall|i: int| 0 <= i && i < index ==> result[i] == sign_val(x[i]),
            result.capacity() >= x.len(),
    {
        let value = x[index];
        if value < 0 {
            result.push(-1);
        } else if value > 0 {
            result.push(1);
        } else {
            result.push(0);
        }
        index = index + 1;
    }
    
    result
}

}
